import json,hashlib,subprocess,html
from pathlib import Path
from datetime import datetime
D=Path(__file__).resolve().parent
W=next(p for p in D.parents if (p/'apps/sgenaxis-desktop').exists())
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def write(n,v):(D/n).write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
spans=[]
for file,a,b,meaning in [
('crates/sgenaxis-ports/src/file_commit.rs',21,27,'四欄單檔 CommitReceipt：沒有 document/session/revision/semantic digest、Held issuer、root-transfer或ACK欄位'),
('crates/sgenaxis-ports/src/file_commit.rs',58,74,'FileWriteLease read/replace 單檔輸出埠，不定義 M05 root-transfer 或 M04 ACK'),
('crates/sgenaxis-adapters/src/file_commit.rs',967,998,'成功分支先核對發布 bytes 與 journal，再構造四欄 receipt；raw byte digest 不等 document semantic digest'),
('crates/sgenaxis-host/src/scene_doc.rs',61,79,'目前 scene save helper 透過 FileSystemPort.write_atomic 回傳 path；此函式未呼叫 FileCommitPort/root-transfer/semantic ACK'),
('crates/sgenaxis-work/src/document_edit.rs',272,295,'capture 為 immutable document/session/revision/content；formal ACK 接收 revision+digest 並更新 formal_baseline'),
('crates/sgenaxis-work/src/document_edit.rs',298,311,'recovery ACK 更新 snapshot_baseline，與 formal baseline 分離'),
('crates/sgenaxis-work/src/document_edit.rs',354,384,'ACK 校驗 editable/digest/future revision/baseline monotonic；dirty 比較 semantic digest'),
('crates/sgenaxis-work/src/asset_reference.rs',1,58,'M05-S1純策略資料：owner-supplied roots/Retain/Eligible，並非 authenticated Held receipt'),
('crates/sgenaxis-work/src/asset_reference.rs',137,182,'missing/unknown/stale root 導致保留；Eligible 僅回 identity，不是 root transfer、cleanup lease 或刪除授權')]:
 p=W/'apps/sgenaxis-desktop'/file;lines=p.read_text(encoding='utf-8').splitlines();spans.append({'id':'SRC-%02d'%(len(spans)+1),'path':str(p.relative_to(W)).replace('\\','/'),'sha256':sha(p),'start':a,'end':b,'text':'\n'.join(lines[a-1:b]),'meaning':meaning})
write('source-spans.json',spans)
sourcefiles=['docs/requirements-confirmation/phase1-spec/tasks/PD-P1-M04-PREP-01.json','docs/requirements-confirmation/phase1-spec/tasks/M04/planning/save-retention-observation-proposal/module-spec.json','docs/requirements-confirmation/phase1-spec/tasks/M01/planning/s2-green/source-current.json','AGENTS.md']
