for term in ['acknowledge_formal_save','evaluate_asset_retention']:
 cmd=['rg','-n',term,'apps/sgenaxis-desktop/crates/sgenaxis-host/src','-g','*.rs'];r=subprocess.run(cmd,cwd=W,capture_output=True,text=True);search.append({'command':cmd,'exit':r.returncode,'stdout':r.stdout,'stderr':r.stderr,'limit':'Only HOST src .rs search; no global absence or runtime claim'})
write('search-log.json',search)
authority=json.loads((W/sourcefiles[2]).read_text(encoding='utf-8'))['source_hashes'];drift=[f for f,h in authority.items() if not (W/f).exists() or sha(W/f)!=h]
rows=[{'boundary':'file bytes → document ACK','present':'CommitReceipt four fields; semantic ACK revision+digest','missing':'Source-bound conversion and orchestration proving exact captured tuple; no receipt digest to semantic digest substitution','provider':'M04 codec/projector+IO result mapper','choice':'G1/G3/G4','selected':None}, {'boundary':'M05 retention → save root transfer','present':'Pure owner-supplied RootSnapshot evaluation','missing':'Authenticated issuer receipt/current fence/full tuple and durable root-transfer provider evidence','provider':'M05 issuer/root owner with M04 caller','choice':'G2/G4','selected':None}, {'boundary':'save → captured formal ACK','present':'Pure DocumentSession method with monotonic baseline checks','missing':'Admitted native orchestration receipt→current delivery→root success→ACK proof','provider':'M04 owner + M03 delivery + M05 root provider','choice':'G4','selected':None}]
prior=[{'card':'PD-P1-M01-PREP-01','attempt':'Read new provider-source-map evidence; do not rerun','missing':'CR-D1/2 durable issuer/native lease and CR-D3 exact publication adoption','provider':'M01+IO+Owner'}, {'card':'PD-P1-M02-PREP-01','attempt':'Read new Golden14 candidate/correction status; do not rerun','missing':'GT-D1..4 decisions and admitted definition/design inputs; candidate not adopted','provider':'Owner+M01/M03/M04 input authors'}, {'card':'PD-P1-M03-PREP-01','attempt':'Read preview/media capability and fixture provenance status; do not rerun','missing':'Exact supported subsets/renderer/decoder/threshold choices and native fixtures','provider':'Owner+media provider'}]
spec={'author':'/root/yellow_next_provider','card':'PD-P1-M04-PREP-01','status':'DOCUMENT_SOURCE_MAP_ONLY_PENDING_INDEPENDENT_REVIEW','generated_at':datetime.now().astimezone().isoformat(),'head':subprocess.check_output(['git','rev-parse','HEAD'],cwd=W,text=True).strip(),'branch':subprocess.check_output(['git','branch','--show-current'],cwd=W,text=True).strip(),'authority_count':len(authority),'authority_drift':drift,'historical_head':'31babe87a7ef1e40a0d4bedc523077e7a45d63ab','head_same_as_historical':False,'new_source_facts':spans,'field_bridge_gaps':rows,'earlier_yellow_actions':prior,'scope':'Original M04 preparation only; no product changes or new contract adoption','bdd':{'given':'Existing file receipt, pure document ACK and root policy sources plus pending G1–4 proposal','when':'Map exact source facts and provider bridges','then':'Preserve three distinct authority boundaries; missing evidence never implies root transfer, Held or ACK'},'limits':['Static source evidence only; call-site rg limited to HOST src','No runtime/race/native proof','No admitted schema/Port/Skeleton or valid RED','No historical PASS rerun; product/build/package/native/regression NOT RUN','Independent review PENDING; choices selected=null']}
write('module-spec.json',spec)
checks={'authority796zero':len(authority)==796 and not drift,'nine_exact_spans':len(spans)==9,'all_source_hashes':all(sha(W/f)==h for f,h in bindings.items()),'all_choices_pending':all(x['selected'] is None for x in rows),'receipt_four_fields':all(x in spans[0]['text'] for x in ['target_path','previous_digest','committed_digest','transaction_id']),'ack_separate_baselines':'formal_baseline' in spans[4]['text'] and 'snapshot_baseline' in spans[5]['text']};assert all(checks.values()),checks;write('author-checks.json',{'layer':'new static author checks only','checks':checks,'independent_review':'NOT RUN'})
sections=''.join('<h2>'+html.escape(s['id']+' '+s['meaning'])+'</h2><p>'+html.escape(s['path']+':'+str(s['start'])+'-'+str(s['end']))+'</p><pre>'+html.escape(s['text'])+'</pre>' for s in spans)
page='<!doctype html><meta charset="utf-8"><title>M04 provider source map</title><style>body{max-width:1100px;margin:30px auto;font:16px system-ui}pre{white-space:pre-wrap;background:#eee;padding:15px}table,td,th{border:1px solid #aaa;border-collapse:collapse;padding:8px}</style><h1>M04 保存收據、root transfer、semantic ACK：來源對照</h1><p>新增靜態來源對照；非產品驗收，未採納 G1–G4。單檔 bytes、M05 retention authority、M04 semantic ACK 是三個不同證據邊界。</p><p>HOST scene save helper 仍經 FileSystemPort.write_atomic 回 path；本次限定搜尋 HOST src 未見純 ACK/retention evaluator 的呼叫，不能擴張成全 repo 缺失或 runtime 結論。</p><h2>三個責任缺口與供料人</h2><pre>'+html.escape(json.dumps(rows,ensure_ascii=False,indent=2))+'</pre><h2>較早黃卡逐項條件</h2><pre>'+html.escape(json.dumps(prior,ensure_ascii=False,indent=2))+'</pre>'+sections+'<h2>驗證與限制</h2><pre>'+html.escape(json.dumps({'checks':checks,'limits':spec['limits']},ensure_ascii=False,indent=2))+'</pre><script type="application/json" id="module-spec">'+json.dumps(spec,ensure_ascii=False).replace('</','<\/')+'</script>'
(D/'index.html').write_text(page,encoding='utf-8')
write('seal.json',{'author':'/root/yellow_next_provider','artifacts':{str(p.relative_to(D)).replace('\\','/'):sha(p) for p in D.rglob('*') if p.is_file() and p.name!='seal.json'},'state':'SEALED_STOP_WRITES'})
print(json.dumps({'checks':checks,'sealed':True},ensure_ascii=False))
